// src/lib/compare/config.ts
export const OSRM_APP_FORMULA = { B0: 60, LEN_KNOTS: [0.5, 1, 2, 4, 8, 15], R_KNOTS: [2, 4, 6, 9, 12], coef: { /* app_formula.json → coef */ } };
const CX = 38.9753, CY = 45.0355, KX = 111.2 * Math.cos((45.0355 * Math.PI) / 180), KY = 111.2;
function southBank(p: GeoPoint) { return okrugOfPoint(p) === null && p.lat < 45.045 && p.lon > 38.85 && p.lon < 39.2; }
export function osrmMinutes(a: GeoPoint, b: GeoPoint, distM: number, durS: number): number {
  const F = OSRM_APP_FORMULA, c = F.coef as Record<string, number>;
  const xa = (a.lon - CX) * KX, ya = (a.lat - CY) * KY, xb = (b.lon - CX) * KX, yb = (b.lat - CY) * KY;
  const ra = Math.hypot(xa, ya), rb = Math.hypot(xb, yb);
  const dx = xb - xa, dy = yb - ya, L2 = dx * dx + dy * dy;
  const u = L2 === 0 ? 0 : Math.min(1, Math.max(0, -(xa * dx + ya * dy) / L2));
  const rmin = Math.hypot(xa + u * dx, ya + u * dy);
  const lk = Math.log(Math.max(distM / 1000, 0.1)), ld = Math.log(Math.max(Math.hypot(dx, dy), 0.1));
  const pos = (v: number) => Math.max(0, v);
  let z = c.c + c.ls * Math.log(durS + F.B0) + c.lk * lk + c.ld * ld;
  for (const k of F.LEN_KNOTS) z += c[`ld>${k}`] * pos(ld - Math.log(k)) + c[`lk>${k}`] * pos(lk - Math.log(k));
  for (const k of F.R_KNOTS) z += c[`r>${k}`] * (pos(ra - k) + pos(rb - k));
  z += c["rmin<3"] * (rmin < 3 ? 1 : 0) + c.cross * (southBank(a) !== southBank(b) ? 1 : 0);
  z += c.north * (pos(ya) + pos(yb)) + c.south * (pos(-ya) + pos(-yb)) + c.east * (pos(xa) + pos(xb)) + c.west * (pos(-xa) + pos(-xb));
  const base = durS + 23; // защита: формула подобрана на поездках до ~46 км и до ~20 км от центра
  return Math.min(1.3 * base, Math.max(0.6 * base, Math.exp(z))) / 60;
}
